import type { TimeframeV2 } from '../../../core/types/time.js';
import type { _CalendarType } from '../../date-picker/calendar/Calendar.js';

/**
 * Keeps the offset as ISO string to keep the precision.
 * @internal
 */
export type _StringTimeOffset = string | { from: string; to: string };

/**
 * Typeguard function that will check if the date is a date range.
 * @internal
 */
export function _isTimeframeV2(
  date: unknown,
  type: _CalendarType,
): date is Partial<TimeframeV2> | TimeframeV2 {
  return type === 'range';
}
